 std: ['S1085', 'S1117', 'S5257', 'S5258'],
 method: { goals: ['Žiak zoradí hlavné medzníky od vzniku Československa po vznik Slovenskej republiky.', 'Žiak vysvetlí príčiny rozdelenia Československa.', 'Žiak uvedie hlavné zmeny po roku 1989.'],
  plan: [['5 min', 'Otázka: v koľkých štátoch žili vaši starí rodičia bez toho, aby sa odsťahovali?'], ['15 min', 'Časová os.'], ['15 min', 'Rozhovor so starými rodičmi alebo práca s dobovou fotografiou.'], ['10 min', 'Rozdelenie Československa a kvíz.']],
  ask: ['Prečo sa Československo rozdelilo pokojne?', 'Čo sa zmenilo v živote ľudí po roku 1989?'] },
 guide: { primer: 'Československo vzniklo 28. októbra 1918 po rozpade Rakúsko-Uhorska. Slováci sa k nemu prihlásili 30. októbra 1918 Martinskou deklaráciou. Prvá republika bola demokratická. V rokoch 1939 až 1945 existoval Slovenský štát závislý od Nemecka. Po vojne sa Československo obnovilo. Vo februári 1948 prevzali moc komunisti a štát sa stal totalitným. Po okupácii v auguste 1968 vznikla 1. januára 1969 federácia, v ktorej existovala Slovenská socialistická republika. Nežná revolúcia v novembri 1989 priniesla demokraciu. 1. septembra 1992 prijala Slovenská národná rada Ústavu Slovenskej republiky. Československo sa pokojne rozdelilo a 1. januára 1993 vznikla samostatná Slovenská republika.',
  steps: [
   { time: '5 min', do: 'Ukážte bankovky alebo mince z rôznych období: koruny československé, slovenské, eurá.', say: 'Prečo sa u nás tak často menili peniaze?', check: 'Žiaci spoja peniaze so zmenami štátu.' },
   { time: '15 min', do: 'Prejdite časovú os. Pri každom medzníku sa pýtajte, či bol štát demokratický.', say: 'V ktorých obdobiach mohli ľudia slobodne voliť?', check: 'Žiaci rozlíšia demokratické a nedemokratické obdobia.' },
   { time: '15 min', do: 'Skupiny pracujú s dobovou fotografiou alebo s rozhovorom, ktorý žiaci urobili doma.', check: 'Skupina zaradí fotografiu alebo príbeh na časovú os.' },
   { time: '10 min', do: 'Príčiny rozdelenia Československa a kvíz.', check: 'Žiak uvedie aspoň jednu príčinu rozdelenia.' }],
  traps: [['Slovensko je samostatné od roku 1939.', 'Slovenský štát v rokoch 1939 až 1945 bol závislý od Nemecka. Dnešná Slovenská republika vznikla 1. januára 1993.'], ['O rozdelení Československa rozhodlo referendum.', 'Referendum sa nekonalo. O rozdelení rozhodli politici a parlament.'], ['Po roku 1948 bolo Československo demokratické.', 'Od februára 1948 vládla komunistická strana a ľudia nemali slobodné voľby.']],
  qa: [['Prečo sa hovorí o zamatovom rozvode?', 'Rozdelenie Československa prebehlo pokojne, bez násilia.'], ['Kedy vstúpilo Slovensko do Európskej únie?', '1. mája 2004. Do NATO vstúpilo 29. marca 2004.']] },
