  quiz: [{ q: 'Ktorý štát vznikol v roku 1918?', o: ['Československo', 'Slovenská republika', 'Rakúsko-Uhorsko'], k: 0, w: 'Československo vzniklo po rozpade Rakúsko-Uhorska.' }, { q: 'Kedy sa začala vláda komunistov?', o: ['1948', '1918', '1993'], k: 0, w: 'Vo februári 1948 prevzali komunisti moc.' }, { q: 'Ako sa rozdelilo Československo?', o: ['Pokojne', 'Po vojne', 'Po referende'], k: 0, w: 'Rozdelenie bolo pokojné a referendum sa nekonalo.' }, { q: 'Kedy vstúpilo Slovensko do Európskej únie?', o: ['V roku 2004', 'V roku 1993', 'V roku 2009'], k: 0, w: 'Do EÚ sme vstúpili 1. mája 2004. V roku 2009 sme prijali euro.', l: 2 }],
