 id: 'bezpecne-na-ceste', title: 'Bezpečne na ceste', aka: ['Dopravná výchova', 'Chodec', 'Semafor', 'Cesta do školy', 'Bezpečnosť na ceste'], subject: 'Človek a príroda', grade: 2, kind: 'pojmy', rec: 'mind',
